CREATE OR REPLACE FUNCTION public.institution_indicators(_institution_id uuid) RETURNS TABLE(students bigint,enrollments bigint,hours numeric,completion numeric) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.organization_permission(_institution_id,'ies','relatorios') THEN RAISE EXCEPTION 'Relatórios exigem acesso institucional sem restrição de escopo'; END IF; RETURN QUERY SELECT (SELECT count(*) FROM public.learner_profiles p WHERE p.institution_id=_institution_id AND p.profile_role='estudante'),(SELECT count(*) FROM public.enrollments e JOIN public.learner_profiles p ON p.user_id=e.user_id AND p.profile_role=e.profile_role WHERE p.institution_id=_institution_id AND p.profile_role='estudante'),(SELECT COALESCE(sum(c.hours),0) FROM public.certificates c JOIN public.learner_profiles p ON p.user_id=c.user_id AND p.profile_role=c.profile_role WHERE p.institution_id=_institution_id AND p.profile_role='estudante'),(SELECT COALESCE(round(100.0*count(*) FILTER(WHERE e.progress>=100)/NULLIF(count(*),0)),0) FROM public.enrollments e JOIN public.learner_profiles p ON p.user_id=e.user_id AND p.profile_role=e.profile_role WHERE p.institution_id=_institution_id AND p.profile_role='estudante'); END $$;
CREATE POLICY organization_company_read ON public.companies AS RESTRICTIVE FOR SELECT TO public USING(auth.uid() IS NULL OR public.current_profile_role()<>'empresa' OR public.organization_member(id,'empresa'));
CREATE POLICY organization_institution_read ON public.institutions AS RESTRICTIVE FOR SELECT TO public USING(auth.uid() IS NULL OR public.current_profile_role()<>'ies' OR public.organization_member(id,'ies'));
CREATE OR REPLACE FUNCTION public.organization_access_options() RETURNS TABLE(organization_id uuid,organization_type text,name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT c.id,'empresa',c.name FROM public.companies c WHERE c.owner_id=auth.uid() OR EXISTS(SELECT 1 FROM public.organization_memberships m WHERE m.organization_id=c.id AND m.organization_type='empresa' AND m.user_id=auth.uid() AND m.status='ativo') UNION ALL SELECT i.id,'ies',i.name FROM public.institutions i WHERE i.owner_id=auth.uid() OR EXISTS(SELECT 1 FROM public.organization_memberships m WHERE m.organization_id=i.id AND m.organization_type='ies' AND m.user_id=auth.uid() AND m.status='ativo') $$;
REVOKE ALL ON FUNCTION public.organization_access_options() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.organization_access_options() TO authenticated;
CREATE POLICY professor_profile_guard ON public.profiles AS RESTRICTIVE FOR SELECT TO authenticated USING(id=auth.uid() OR public.current_profile_role() NOT IN('professor','ies','colaborador'));
CREATE OR REPLACE FUNCTION public.expire_student_verifications() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v record; n integer:=0; BEGIN FOR v IN SELECT * FROM public.student_verifications WHERE status='validado' AND valid_until<=now() LOOP IF auth.uid()<>v.user_id AND NOT public.can_validate_student(v.institution_id,v.scope_id) THEN CONTINUE; END IF; UPDATE public.student_verifications SET status='expirado' WHERE id=v.id; INSERT INTO public.notifications(user_id,profile_role,title,body) VALUES(v.user_id,'estudante','Vínculo expirado','Envie nova declaração para emitir horas complementares. Seu aprendizado continua disponível.');n:=n+1;END LOOP;RETURN n;END $$;
REVOKE ALL ON FUNCTION public.expire_student_verifications() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.expire_student_verifications() TO authenticated;